class_name ConversationMemory
extends RefCounted
## Detached per-person value. Only NpcDialogueService publishes accepted changes.
const MAX_AFFINITY: int = 2147483647
var npc_id: String
var affinity: int = 0
var flags: PackedStringArray = []
var learned_fact_ids: PackedStringArray = []
var seen_node_ids: PackedStringArray = []
var applied_choice_ids: PackedStringArray = []

func _init(id: String = "") -> void:
	npc_id = id

func level(threshold: int) -> int:
	return 1 if affinity >= threshold else 0

func detached_copy() -> ConversationMemory:
	var result: ConversationMemory = ConversationMemory.new(npc_id)
	result.affinity = affinity
	result.flags = flags.duplicate()
	result.learned_fact_ids = learned_fact_ids.duplicate()
	result.seen_node_ids = seen_node_ids.duplicate()
	result.applied_choice_ids = applied_choice_ids.duplicate()
	return result

func entered(node: NpcDialogueGraph.NodeDefinition) -> ConversationMemory:
	var result: ConversationMemory = detached_copy()
	_add_unique(result.seen_node_ids, node.id)
	for id: String in node.revealed_fact_ids:
		_add_unique(result.learned_fact_ids, id)
	return result

func consumed(choice: NpcDialogueGraph.Choice) -> bool:
	return choice.has_one_time_effect() and (choice.id in applied_choice_ids or (not choice.one_time_reward_flag.is_empty() and choice.one_time_reward_flag in flags))

func responded(choice: NpcDialogueGraph.Choice) -> ConversationMemory:
	var result: ConversationMemory = detached_copy()
	if consumed(choice): return result
	result.affinity = clampi(affinity + choice.affinity_delta, 0, MAX_AFFINITY)
	for id: String in choice.added_flags:
		_add_unique(result.flags, id)
	if not choice.one_time_reward_flag.is_empty(): _add_unique(result.flags, choice.one_time_reward_flag)
	if choice.has_one_time_effect(): _add_unique(result.applied_choice_ids, choice.id)
	return result

func snapshot(threshold: int) -> Dictionary:
	return {"npc_id": npc_id, "affinity": affinity, "level": level(threshold), "flags": Array(flags), "learned_fact_ids": Array(learned_fact_ids), "seen_node_ids": Array(seen_node_ids), "applied_choice_ids": Array(applied_choice_ids)}

static func _add_unique(values: PackedStringArray, id: String) -> void:
	if id not in values:
		values.append(id)
		values.sort()

class_name NpcConversationState
extends RefCounted
## Session-owned publication: every person and event aggregate swaps together.
var initialized: bool = false
var _memories: Dictionary[String, ConversationMemory] = {}
var _thresholds: Dictionary[String, int] = {}
var _events: NpcEventMemory = NpcEventMemory.new()

func initialize(catalog: NpcContentCatalog) -> PackedStringArray:
	if initialized: return PackedStringArray(["Conversation state already initialized"])
	if catalog == null or not catalog.initialized: return PackedStringArray(["Conversation state requires validated NPC content"])
	for id: String in catalog.npc_ids():
		_memories[id] = ConversationMemory.new(id)
		_thresholds[id] = catalog.get_npc(id).level_one_affinity
	_events.initialize(catalog)
	initialized = true
	return []

func memory(id: String) -> ConversationMemory:
	return _memories[id].detached_copy() if _memories.has(id) else null

func events() -> NpcEventMemory:
	return _events.detached_copy()

func with_person(value: ConversationMemory, event_value: NpcEventMemory = null) -> NpcConversationState:
	var result: NpcConversationState = detached_copy()
	result._memories[value.npc_id] = value.detached_copy()
	if event_value != null: result._events = event_value.detached_copy()
	return result

func with_events(value: NpcEventMemory) -> NpcConversationState:
	var result: NpcConversationState = detached_copy()
	result._events = value.detached_copy()
	return result

func detached_copy() -> NpcConversationState:
	var result: NpcConversationState = NpcConversationState.new()
	result.initialized = initialized
	result._thresholds = _thresholds.duplicate()
	result._events = _events.detached_copy()
	for id: String in _memories: result._memories[id] = _memories[id].detached_copy()
	return result

func snapshot() -> Dictionary:
	var people: Dictionary = {}
	for id: String in _memories: people[id] = _memories[id].snapshot(_thresholds[id])
	return {"people": people, "events": _events.snapshot()}

class_name NpcEventMemory
extends RefCounted
## Exact keys, fixed allowlist and bounded aggregates; no inventory-derived history.
const MAX_SEQUENCE: int = 2147483647
const MAX_ACTIVE_SECONDS: float = 2190600.0 # 3651 days * existing 600-second day
const AREA: String = "areaEntered"
const GATHER: String = "resourceGathered"
const CHOICE: String = "dialogueChoiceSelected"
var _allowed: Dictionary[String, bool] = {}
var _facts: Dictionary[String, Dictionary] = {}
var _last_sequence: int = 0
var _last_active_seconds: float = 0.0

func initialize(catalog: NpcContentCatalog) -> void:
	_allowed.clear()
	_facts.clear()
	_last_sequence = 0
	_last_active_seconds = 0.0
	_allowed[key(AREA, "woods", null)] = true
	_allowed[key(GATHER, "moonflower", null)] = true
	for id: String in catalog.npc_ids():
		for choice: NpcDialogueGraph.Choice in catalog.get_npc(id).graph.choices.values():
			if choice.availability.is_enabled(): _allowed[key(CHOICE, id, choice.id)] = true

static func key(kind: String, subject: Variant, target: Variant) -> String:
	return JSON.stringify([kind, subject, target])

func record(kind: String, subject: Variant, target: Variant, seconds: float) -> NpcEventMemory:
	var encoded: String = key(kind, subject, target)
	if not _allowed.has(encoded) or not valid_time(seconds) or seconds < _last_active_seconds or _last_sequence >= MAX_SEQUENCE:
		return null
	var result: NpcEventMemory = detached_copy()
	result._last_sequence += 1
	result._last_active_seconds = seconds
	var previous: Dictionary = _facts.get(encoded, {})
	result._facts[encoded] = {"kind": kind, "subject_id": subject, "target_id": target, "count": int(previous.get("count", 0)) + 1, "first_sequence": int(previous.get("first_sequence", result._last_sequence)), "last_sequence": result._last_sequence, "first_active_seconds": float(previous.get("first_active_seconds", seconds)), "last_active_seconds": seconds}
	return result

static func valid_time(seconds: float) -> bool:
	return is_finite(seconds) and seconds >= 0.0 and seconds <= MAX_ACTIVE_SECONDS

func count(kind: String, subject: Variant, target: Variant) -> int:
	return int(_facts.get(key(kind, subject, target), {}).get("count", 0))

func matches(condition: NpcDialogueGraph.EventCondition, seconds: float) -> bool:
	if not valid_time(seconds): return false
	var kind: String = NpcContentCatalog.EVENT_KINDS[condition.kind]
	var fact: Dictionary = _facts.get(key(kind, condition.subject_id, condition.target_id), {})
	var observed: int = int(fact.get("count", 0))
	if observed < condition.minimum_count or (condition.maximum_count >= 0 and observed > condition.maximum_count): return false
	if condition.occurred_within_active_seconds < 0.0: return true
	# Source latest-event window is inclusive; null never means wildcard.
	return not fact.is_empty() and seconds - float(fact["last_active_seconds"]) <= condition.occurred_within_active_seconds

func detached_copy() -> NpcEventMemory:
	var result: NpcEventMemory = NpcEventMemory.new()
	result._allowed = _allowed.duplicate()
	result._facts = _facts.duplicate(true)
	result._last_sequence = _last_sequence
	result._last_active_seconds = _last_active_seconds
	return result

func snapshot() -> Dictionary:
	var rows: Array[Dictionary] = []
	var keys: Array[String] = []
	keys.assign(_facts.keys())
	keys.sort()
	for encoded: String in keys: rows.append(_facts[encoded].duplicate(true))
	return {"last_sequence": _last_sequence, "facts": rows}

func supported_key_count() -> int:
	return _allowed.size()

func initialize(catalog: NpcContentCatalog, session: GameSession) -> PackedStringArray:
	if catalog == null or not catalog.initialized or session == null or not session.initialized:
		return PackedStringArray(["Dialogue requires validated content and initialized session"])
	if not session.conversations.initialized:
		var errors: PackedStringArray = session.conversations.initialize(catalog)
		if not errors.is_empty(): return errors
	_catalog = catalog
	_session = session
	_clear()
	return []

func active() -> bool:
	return not _node_id.is_empty()

func begin(npc_id: String, instance_id: String) -> Result:
	if _session == null or active() or instance_id.strip_edges().is_empty(): return Result.new(false, "Conversation owner unavailable, active or invalid instance.")
	var npc: NpcDefinition = _catalog.get_npc(npc_id)
	var memory: ConversationMemory = _session.conversations.memory(npc_id)
	var node: NpcDialogueGraph.NodeDefinition = NpcDialogueRules.resolve(npc, memory, _session.conversations.events(), _session.elapsed_play_seconds)
	if node == null: return Result.new(false, "No available ordinary entry.")
	_session.conversations = _session.conversations.with_person(memory.entered(node))
	_cursor_state = _session.conversations
	_npc_id = npc_id
	_instance_id = instance_id

func choose(npc_id: String, instance_id: String, node_id: String, token: String, choice_id: String) -> Result:
	if not _command_matches(npc_id, instance_id, node_id, token): return Result.new(false, "Stale or foreign conversation command.")
	if _prototype != null: return _choose_prototype(choice_id)
	var npc: NpcDefinition = _catalog.get_npc(_npc_id)
	var node: NpcDialogueGraph.NodeDefinition = npc.graph.nodes[_node_id]
	var choice: NpcDialogueGraph.Choice
	for row: NpcDialogueGraph.Choice in node.choices:
		if row.id == choice_id: choice = row
	if choice == null: return Result.new(false, "Unknown response on current node.")
	var memory: ConversationMemory = _session.conversations.memory(_npc_id)
	var reason: String = NpcDialogueRules.choice_reason(npc, choice, memory, _session.conversations.events(), _session.elapsed_play_seconds)
	if not reason.is_empty(): return Result.new(false, reason)
	var next: NpcDialogueGraph.NodeDefinition
	if not choice.ends_conversation and not choice.target_node_id.is_empty():
		next = npc.graph.nodes.get(choice.target_node_id)
		if next == null or not next.availability.is_enabled(): return Result.new(false, "Response target unavailable.")
	# Edric milestone is deferred; never inject it merely for crossing level one.
	var event_value: NpcEventMemory = _session.conversations.events().record(NpcEventMemory.CHOICE, _npc_id, choice.id, _session.elapsed_play_seconds)
	if event_value == null: return Result.new(false, "Event memory range exhausted or invalid active time.")
	var candidate: ConversationMemory = memory.responded(choice)
	if next != null: candidate = candidate.entered(next)
	_session.conversations = _session.conversations.with_person(candidate, event_value)
	_cursor_state = _session.conversations
	if next == null: _clear()
	else:
		_node_id = next.id
		_selected_choice = choice_id
		_generation += 1
	changed.emit()
	return Result.new(true, "Response accepted.")

static func restore(data: Variant, catalog: NpcContentCatalog, seconds: float) -> Result:
	var result: Result = Result.new()
	if catalog == null or not catalog.initialized or not data is Dictionary or not SaveCodec._exact_fields(data, ["people", "events"]):
		return _fail(result, "conversations requires exactly people/events and validated catalog")
	if not _independent_containers(data): return _fail(result, "shared/cyclic mutable save containers")
	var people_ids: Array[String] = []; people_ids.assign(catalog.npc_ids())
	if not data.people is Dictionary or not SaveCodec._exact_fields(data.people, people_ids):
		return _fail(result, "conversations requires exactly the eight pinned people")
	var state: NpcConversationState = NpcConversationState.new()
	state.initialize(catalog)
	var events: NpcEventMemory = state.events()
	var raw: Variant = data.events
	if not raw is Dictionary or not SaveCodec._exact_fields(raw, ["last_sequence", "facts"]) or not SaveCodec._integer(raw.last_sequence, 0, NpcEventMemory.MAX_SEQUENCE) or not raw.facts is Array or raw.facts.size() > events.supported_key_count():
		return _fail(result, "invalid bounded event envelope")
	var total: int = 0
	var endpoints: Dictionary[int, float] = {}
	for value: Variant in raw.facts:

	var person: Variant = data.people[id]
	if not person is Dictionary or not SaveCodec._exact_fields(person, ["npc_id", "affinity", "level", "flags", "learned_fact_ids", "seen_node_ids", "applied_choice_ids"]) or not person.npc_id is String or person.npc_id != id:
		return _fail(result, "invalid memory identity/fields for " + id)
	if not SaveCodec._integer(person.affinity, 0, ConversationMemory.MAX_AFFINITY) or not SaveCodec._integer(person.level, 0, 1):
		return _fail(result, "invalid memory affinity/level")
	for field: String in ["flags", "learned_fact_ids", "seen_node_ids", "applied_choice_ids"]:
		if not _unique_strings(person[field]): return _fail(result, "invalid independent memory set " + field)
	var expected_facts: PackedStringArray = []
	for node_id: String in person.seen_node_ids:
		var node: NpcDialogueGraph.NodeDefinition = npc.graph.nodes.get(node_id)
		if node == null or not node.availability.is_enabled(): return _fail(result, "foreign/deferred seen node")
		for fact_id: String in node.revealed_fact_ids: ConversationMemory._add_unique(expected_facts, fact_id)
	var expected_flags: PackedStringArray = []
	var expected_receipts: PackedStringArray = []
	var expected_affinity: int = 0
	for choice: NpcDialogueGraph.Choice in npc.graph.choices.values():
		var count: int = events.count(NpcEventMemory.CHOICE, id, choice.id)
		if count == 0: continue
		if choice.has_one_time_effect():
			if count != 1: return _fail(result, "one-time choice repeated")
			ConversationMemory._add_unique(expected_receipts, choice.id)
		for flag: String in choice.added_flags: ConversationMemory._add_unique(expected_flags, flag)
		if not choice.one_time_reward_flag.is_empty(): ConversationMemory._add_unique(expected_flags, choice.one_time_reward_flag)
		expected_affinity += choice.affinity_delta * count
		# Current pin has only nonnegative deltas; reject drift rather than invent order.
		if choice.affinity_delta < 0: return _fail(result, "signed affinity requires ordered persistence policy")
		var owner_node: NpcDialogueGraph.NodeDefinition
		for node: NpcDialogueGraph.NodeDefinition in npc.graph.nodes.values():
			if choice in node.choices: owner_node = node
		if owner_node == null or owner_node.id not in person.seen_node_ids or (not choice.target_node_id.is_empty() and choice.target_node_id not in person.seen_node_ids):
			return _fail(result, "choice event missing authored entry/target")
	# Pinned ordinary introductions are mutually exclusive, even neutral rewards.
	if expected_receipts.size() > 1: return _fail(result, "opposite introduction receipts")
	if not _same_set(person.learned_fact_ids, expected_facts) or not _same_set(person.flags, expected_flags) or not _same_set(person.applied_choice_ids, expected_receipts) or int(person.affinity) != clampi(expected_affinity, 0, ConversationMemory.MAX_AFFINITY):
		return _fail(result, "memory disclosure/reward/event derivation mismatch")
	var memory: ConversationMemory = ConversationMemory.new(id)
	memory.affinity = int(person.affinity)
	if memory.level(npc.level_one_affinity) != int(person.level): return _fail(result, "derived relationship level mismatch")
	memory.flags = PackedStringArray(person.flags); memory.flags.sort()
	memory.learned_fact_ids = PackedStringArray(person.learned_fact_ids); memory.learned_fact_ids.sort()
	memory.seen_node_ids = PackedStringArray(person.seen_node_ids); memory.seen_node_ids.sort()
	memory.applied_choice_ids = PackedStringArray(person.applied_choice_ids); memory.applied_choice_ids.sort()
	state = state.with_person(memory)
result.state = state
return result

class_name ItemDefinition
extends ContentDefinition
## Immutable authored item metadata; ownership and selection belong to InventoryState.

@export var source_item_id: String = ""
@export_enum("forage", "tool") var category: String = "forage"
@export var stack_limit: int = 99
@export var movable_pickup: bool = false
@export_multiline var description: String = ""


func validation_errors() -> PackedStringArray:
	var errors: PackedStringArray = super.validation_errors()
	if source_item_id.is_empty() or source_item_id != source_item_id.strip_edges():
		errors.append("source_item_id must be nonempty with no surrounding whitespace")
	if category not in ["forage", "tool"]:
		errors.append("item category must be forage or tool")
	if stack_limit < 1 or stack_limit > 99:
		errors.append("stack_limit must be in 1..99")
	if movable_pickup and category != "tool":
		errors.append("movable pickup must be a tool")
	if description.strip_edges().is_empty():
		errors.append("item description must be nonempty")
	return errors


func is_tool() -> bool:
	return category == "tool"

class_name InventoryState
extends RefCounted
## Pure session-owned rules. No scene, signal, reward, UI or save ownership.
## Commands accept integer Variants deliberately: typed int arguments coerce fractions.

const MAX_TYPES: int = 20

var initialized: bool = false
var _catalog: ContentCatalog
var _item_counts: Dictionary[String, int] = {}
var _active_item_id: String = ""
var _revision: int = 0


func initialize(catalog: ContentCatalog) -> PackedStringArray:
	if initialized:
		return PackedStringArray(["inventory is already initialized"])
	if catalog == null or not catalog.initialized:
		return PackedStringArray(["inventory requires an initialized content catalog"])
	_catalog = catalog
	initialized = true
	return []


func revision() -> int:
	return _revision


func snapshot() -> InventorySnapshot:
	return InventorySnapshot.new(_item_counts, null if _active_item_id.is_empty() else _active_item_id)


func count(item_id: String) -> int:
	return _item_counts.get(item_id, 0)


func active_tool() -> ItemDefinition:
	if not initialized or _active_item_id.is_empty():
		return null
	var definition: ItemDefinition = _catalog.get_item(_active_item_id)
	return definition if definition != null and definition.is_tool() else null


func can_add(item_id: String, quantity: Variant = 1) -> PackedStringArray:
	var errors: PackedStringArray = _validate_command(item_id, quantity)
	if not errors.is_empty():
		return errors
	var definition: ItemDefinition = _catalog.get_item(item_id)
	# Subtraction before addition prevents integer overflow for hostile quantities.
	if quantity > definition.stack_limit - count(item_id):
		return PackedStringArray(["stack_full"])
	if not _item_counts.has(item_id) and _item_counts.size() >= MAX_TYPES:
		return PackedStringArray(["backpack_full"])
	return []


func add(item_id: String, quantity: Variant = 1) -> PackedStringArray:
	var errors: PackedStringArray = can_add(item_id, quantity)
	if errors.is_empty():
		_item_counts[item_id] = count(item_id) + int(quantity)
		_revision += 1
	return errors


func consume(item_id: String, quantity: Variant = 1) -> PackedStringArray:
	var errors: PackedStringArray = _validate_command(item_id, quantity)
	if not errors.is_empty():
		return errors
	if quantity > count(item_id):
		return PackedStringArray(["insufficient_items"])
	_revision += 1
	var remaining: int = count(item_id) - int(quantity)
	if remaining == 0:
		_item_counts.erase(item_id)
		if _active_item_id == item_id:
			_active_item_id = ""
	else:
		_item_counts[item_id] = remaining
	return []


func select(item_id: Variant) -> PackedStringArray:
	if not initialized:
		return PackedStringArray(["inventory is not initialized"])
	if item_id == null:
		if not _active_item_id.is_empty():
			_revision += 1
		_active_item_id = ""
		return []
	if not item_id is String or _catalog.get_item(item_id) == null:
		return PackedStringArray(["unknown_item"])
	if count(item_id) == 0:
		return PackedStringArray(["missing_owned_item"])
	if _active_item_id != item_id:
		_revision += 1
	_active_item_id = item_id
	return []


func _validate_command(item_id: String, quantity: Variant) -> PackedStringArray:
	if not initialized:
		return PackedStringArray(["inventory is not initialized"])
	if _catalog.get_item(item_id) == null:
		return PackedStringArray(["unknown_item"])
	if typeof(quantity) != TYPE_INT or quantity <= 0:
		return PackedStringArray(["invalid_quantity"])
	return []

class_name ForagingRegistry
extends RefCounted
## F001 pinned identities/source feet, with user-approved safe runtime relocations.

const LOCATION: String = "prototype-alderwake"
const ROD_ORIGIN: String = "fishing-rod-dock-01"
const ROD_ITEM: String = "item-fishing-rod"
const ROD_RESOURCE: String = "resource-fishing-rod"
const DROP_ID: String = "dropped-fishing_rod"
const PLACEMENT_LOCATIONS: PackedStringArray = ["prototype-alderwake", "prototype-tollworks"]
# Approved 2026-10-07: rod centred on east dock, flower east of cliff.
# Preserve pinned source geography; saved placements override these defaults.
const RUNTIME_FEET: Dictionary = {
	ROD_ORIGIN: Vector3(-6.5, 0, 15.75),
	"moonflower-01": Vector3(26.75, 0.25, -2),
}
const ROWS: Array = [
	[ROD_ORIGIN, ROD_RESOURCE, ROD_ITEM, Vector3(-8, 0, 15.75)],
	["moonflower-01", "resource-moonflower", "item-moonflower", Vector3(26, 0.25, -2)],
	["moonflower-02", "resource-moonflower", "item-moonflower", Vector3(34, 0.25, 7)],
	["moonflower-03", "resource-moonflower", "item-moonflower", Vector3(30, 0.5, -9)],
]


static func entries() -> Array[Dictionary]:
	var result: Array[Dictionary] = []
	for row: Array in ROWS:
		result.append({"instance_id": row[0], "resource_id": row[1], "item_id": row[2], "location_id": LOCATION, "authored_foot": row[3], "foot": RUNTIME_FEET.get(row[0], row[3])})
	return result


static func find(instance_id: String) -> Dictionary:
	for entry: Dictionary in entries():
		if entry.instance_id == instance_id:
			return entry
	return {}


static func validation_errors(catalog: ContentCatalog) -> PackedStringArray:
	for entry: Dictionary in entries():
		var resource: ForagingResourceDefinition = catalog.get_resource(entry.resource_id)
		if catalog.get_location(entry.location_id) == null or resource == null or resource.item_id != entry.item_id or catalog.get_item(entry.item_id) == null:
			return PackedStringArray(["foraging registry references absent/mismatched content"])
	for location: String in PLACEMENT_LOCATIONS:
		if catalog.get_location(location) == null:
			return PackedStringArray(["foraging placement location is missing"])
	return []

var _placement_validator: Callable
var _restored: bool = false


func initialize(catalog: ContentCatalog, session: GameSession) -> PackedStringArray:
	if initialized or catalog == null or not catalog.initialized or session == null or not session.inventory.initialized:
		return PackedStringArray(["foraging requires a fresh state, catalog and session inventory"])
	var errors: PackedStringArray = ForagingRegistry.validation_errors(catalog)
	if not errors.is_empty():
		return errors
	_catalog = catalog

func revision() -> int:
	var session: GameSession = _session()
	return _world_revision + (session.inventory.revision() if session != null else 0)


func snapshot() -> Dictionary:
	var placements: Array[Dictionary] = []
	var ids: Array[String] = _placements.keys()
	ids.sort()
	for id: String in ids:
		placements.append(_placements[id].to_dictionary())

